mapper.update:
update sky_take_out.order_comment
order_id = #{orderId}, user_id = #{userId}, score = #{score}, content = #{content}, ai_optimized = #{aiOptimized}, create_time = #{createTime}, reply_content = #{replyContent}, status = #{status},
where id = #{id}

mapper.select:
select count(*)
from sky_take_out.order_comment
where score <= 2
  and create_time >= #{beginTime}
  and create_time <= #{endTime}
